/// <summary>
/// designed by AVANADE
/// </summary>
[ExtensionOf(formDataSourceStr(SalesCopying, CustQuotationTrans))]
final class AVASalesCopyingQuotTransFrmDS_Extension
{
}

Method.Source:
/// <summary>
/// designed by AVANADE see also AVASalesCopyingFrmDS_Extension.quotationMarkAll
/// </summary>
/// <param name = "_set">boolean</param>
/// <param name = "_custQuotationTrans">CustQuotationTrans</param>
/// <param name = "_copy">NoYes</param>
/// <returns>NoYes</returns>
edit NoYes copy(boolean             _set,
                    CustQuotationTrans  _custQuotationTrans,
                    NoYes               _copy)
{
    int                 numOfDays;
    CustQuotationJour   custQuotationJour = _custQuotationTrans.custQuotationJour();
    FormCheckBoxControl markAll;

    markAll = this.formRun().design().controlName(formControlStr(SalesCopying, QuotationMarkAll));

    if (!markAll.checked())
    {
        if (_set  && _copy && custQuotationJour.RespiteDate < DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()))
        {
            numOfDays   = date2Num(DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone())) - date2Num(custQuotationJour.RespiteDate);
            Info(strFmt("@NDX:NXANumOfDaysWarning", numOfDays));
        }
    }

    return next copy(_set, _custQuotationTrans, _copy);
}
